CREATE TABLE "trained_lessons" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" BIGINT NOT NULL,
    "dog_id" BIGINT NOT NULL,
    "lesson_id" BIGINT NOT NULL,
    "trained_date" DATE NOT NULL,
    "source" VARCHAR(20) NOT NULL,
    "created_at" TIMESTAMP NOT NULL,
    CONSTRAINT "uk_trained_lessons_user_dog_lesson_trained_date_source"
        UNIQUE ("user_id", "dog_id", "lesson_id", "trained_date", "source")
);

CREATE INDEX "idx_trained_lessons_user_dog_trained_date"
    ON "trained_lessons" ("user_id", "dog_id", "trained_date");
